fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // An empty prefix always matches
    if p.is_empty() {
        return true;
    }
    // If v is shorter than p, it can’t start with p
    if v.len() < p.len() {
        return false;
    }
    // Compare elements one by one
    for (vc, pc) in v.iter().zip(p.iter()) {
        if vc != pc {
            return false;
        }
    }
    true
}

fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    let mut filtered = Vec::new();
    for seq in xs {
        if has_prefix(&seq, &p) {
            filtered.push(seq);
        }
    }
    filtered
}

// Example usage
fn main() {
    let words: Vec<Vec<char>> = vec![
        "apple".chars().collect(),
        "application".chars().collect(),
        "banana".chars().collect(),
        "apricot".chars().collect(),
    ];
    let prefix: Vec<char> = "app".chars().collect();

    let result = filter_by_prefix(words, prefix);
    for word in result {
        println!("{}", word.iter().collect::<String>());
    }
}